parameters.text:
=Generate social media content for the topic: "{{ $json.topic }}"

Brand voice: {{ $json.brand_voice }}
Target audience: {{ $json.target_audience }}

Return ONLY valid JSON with this structure:
{
  "twitter": "Tweet (max 280 chars, include 2-3 relevant hashtags)",
  "linkedin": "LinkedIn post (3-4 paragraphs, professional tone, include hashtags)",
  "reddit_title": "Reddit post title (engaging, not clickbait)",
  "reddit_body": "Reddit post body (informative, genuine value, no hard sell)",
  "instagram_caption": "Instagram caption (engaging, with emoji, 5-10 hashtags at end)"
}

parameters.jsCode:
const parse = function parseSocial({ text, topic, original = null }) {
  const fields = ['twitter', 'linkedin', 'reddit_title', 'reddit_body', 'instagram_caption'];
  let parsed;
  try {
    if (typeof text !== 'string') throw new Error('Model output must be text.');
    const match = text.match(/\{[\s\S]*\}/);
    if (!match) throw new Error('No JSON object found.');
    parsed = JSON.parse(match[0]);
    if (!parsed || Array.isArray(parsed) || fields.some((field) => typeof parsed[field] !== 'string' || !parsed[field].trim())) throw new Error('Model output must contain all five nonempty social content fields.');
  } catch (error) {
    if (original) return { result: { ...original, reviewed: false } };
    throw new Error('Failed to parse AI response as complete content JSON: ' + error.message);
  }
  const content = Object.fromEntries(fields.map((field) => [field, parsed[field]]));
  return { result: original ? { ...original, ...content, reviewed: true } : { ...content, topic, generated_at: new Date().toISOString() } };
}

return [{json: parse({text: $input.first().json.text, topic: $('Content Parameters').first().json.topic}).result}];

